// Tính rule nào 'đến hạn' hôm nay: sinh nhật, ngày lễ theo nghề nghiệp, hoặc điều kiện ngày.
// Đây là điểm mở rộng — thêm loại trigger mới chỉ cần thêm 1 case, không đổi cấu trúc.
const today = new Date();
const dd = String(today.getDate()).padStart(2,'0');
const mm = String(today.getMonth()+1).padStart(2,'0');

const rules = $input.first().json.data || [];
const due = rules.filter(r => {
  if (r.trigger_event === 'Vietnamese Teachers Day (20/11)') return dd === '20' && mm === '11';
  if (r.trigger_event === 'Customer Birthday') return true; // lọc theo từng khách ở bước sau
  if (r.trigger_event === 'Days Since Last Service') return true; // điều kiện đã nằm trong audience_filter
  return false;
});
return due.map(r => ({ json: r }));
